package org.transittr;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;
/** TV launcher and remote-friendly configuration. */
public class TvActivity extends Activity {
 private LinearLayout root;private TvBoard board;private int[] ids=CityRegistry.ids();private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xffeef5f1);return t;}private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextSize(16);return b;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LOW_PROFILE);String mode=getIntent().getStringExtra("tv_mode");if("configure".equals(mode)){configure();}else if("preview".equals(mode)){preview();}else{startActivity(new Intent(this,TransitActivity.class));finish();}}
 private void layout(){if(board!=null){board.stop();board=null;}root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(50),dp(28),dp(50),dp(28));root.setBackgroundColor(0xff101719);setContentView(root);}
 private void home(){layout();root.addView(text("TRANSIT TR  /  TV",26));root.addView(text("Duraklarını ekle, varışları uzaktan izle.",17));LinearLayout menu=new LinearLayout(this);menu.setPadding(0,dp(24),0,dp(16));root.addView(menu);Button edit=button("Kayıtları düzenle"),full=button("Pano önizleme"),app=button("Harita / Metro");menu.addView(edit,new LinearLayout.LayoutParams(0,dp(60),1));menu.addView(full,new LinearLayout.LayoutParams(0,dp(60),1));menu.addView(app,new LinearLayout.LayoutParams(0,dp(60),1));edit.setOnClickListener(new View.OnClickListener(){public void onClick(View v){configure();}});full.setOnClickListener(new View.OnClickListener(){public void onClick(View v){preview();}});app.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(TvActivity.this,TransitActivity.class));}});root.addView(text("Ekran koruyucu: TV ayarlarında Transit TR seç.",15));edit.requestFocus();}
 private void preview(){if(board!=null)board.stop();board=new TvBoard(this);setContentView(board);board.start();}
 private void configure(){layout();root.addView(text("Pano kayıtları",24));LinearLayout form=new LinearLayout(this);root.addView(form);final Spinner city=new Spinner(this);city.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,CityRegistry.names()));form.addView(city,new LinearLayout.LayoutParams(dp(120),dp(55)));final EditText stop=new EditText(this),line=new EditText(this);stop.setSingleLine();stop.setHint("Durak no");stop.setInputType(2);line.setSingleLine();line.setHint("Hat kodu");form.addView(stop,new LinearLayout.LayoutParams(dp(110),dp(55)));form.addView(line,new LinearLayout.LayoutParams(dp(110),dp(55)));Button save=button("Ekle");form.addView(save,new LinearLayout.LayoutParams(dp(100),dp(55)));save.setOnClickListener(new View.OnClickListener(){public void onClick(View v){try{WidgetFavorites.add(TvActivity.this,ids[city.getSelectedItemPosition()],stop.getText().toString(),line.getText().toString(),"","");configure();}catch(Exception e){Toast.makeText(TvActivity.this,"Geçerli durak ve hat gir",Toast.LENGTH_LONG).show();}}});final Button frequency=button("Yenileme: "+TvBoard.intervalSeconds(this)+" sn");root.addView(frequency,new LinearLayout.LayoutParams(dp(220),dp(48)));frequency.setOnClickListener(new View.OnClickListener(){public void onClick(View v){final int[] values={30,60,120,300};new AlertDialog.Builder(TvActivity.this).setTitle("Pano yenileme aralığı").setItems(new String[]{"30 saniye","1 dakika","2 dakika","5 dakika"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){getSharedPreferences("tv-board-settings-v1",0).edit().putInt("interval-seconds",values[which]).commit();frequency.setText("Yenileme: "+values[which]+" sn");}}).show();}});ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);for(final WidgetFavorites.Entry e:WidgetFavorites.all(this)){Button remove=button(e.line+" · "+WidgetFavorites.cityName(e.city)+" · "+e.stop+"    KALDIR");list.addView(remove);remove.setOnClickListener(new View.OnClickListener(){public void onClick(View v){WidgetFavorites.remove(TvActivity.this,e.id);configure();}});}city.requestFocus();}
 @Override public void onBackPressed(){finish();}@Override protected void onDestroy(){if(board!=null)board.stop();super.onDestroy();}
}
